 public function fgets():string|false {if(!$this->opened())return false;$line=fgets($this->stream,262145);if($line===false)return false;$this->account(strlen($line));if(strlen($line)>=262144&&!str_ends_with($line,"\n"))throw new RuntimeException('IMAP-Kopfzeile zu groß.');return $line;}
