 private function fetched(array $uids,array $items):array {if(!$uids)return [];$rows=$this->command(fn()=>$this->connection->fetch($items,$uids));$out=[];foreach($rows as $row){$data=$row->tokenAt(3);$uid=(int)($data?->lookup('UID')?->value??0);if(!$uid||!in_array($uid,$uids,true)||isset($out[$uid]))throw new RuntimeException('IMAP-Antwortidentität ungültig.');foreach($items as $item){$field=str_contains($item,'[')?substr($item,strpos($item,'[')):$item;if($data->lookup($field)===null)throw new RuntimeException('IMAP-Antwort unvollständig.');}$out[$uid]=$data;}return $out;}
