  foreach($ids as $id){$row=$sizes[$id]??null;$size=$row?->lookup('RFC822.SIZE')?->value;if(!$row||!is_numeric($size)||(int)$size<0||(int)$size>15*1024*1024)throw new RuntimeException('IMAP-Nachricht fehlt oder überschreitet15MB.');if($out&&$bytes+(int)$size>20*1024*1024){$this->more=true;break;}$data=$this->fetched([$id],['BODY.PEEK[HEADER]','BODY.PEEK[TEXT]'])[$id]??null;$head=$data?->lookup('[HEADER]')?->value;$body=$data?->lookup('[TEXT]')?->value;if(!is_string($head)||!is_string($body)||strlen($head)>262144||strlen($head)+strlen($body)>15*1024*1024)throw new RuntimeException('IMAP-Nachricht unvollständig oder zu groß.');$flags=$row->lookup('FLAGS')?->values()??[];$out[]=['uid'=>$id,'raw'=>$head."\r\n".$body,'seen'=>in_array('\\Seen',$flags,true),'deleted'=>in_array('\\Deleted',$flags,true)];$bytes+=strlen($head)+strlen($body);}
  return $out;
 }
 public function flags(string $folder,array $uids):array {$this->select($folder);$uids=$this->uids($uids,100);$rows=$this->fetched($uids,['FLAGS']);$out=[];foreach($uids as $uid){$flags=isset($rows[$uid])?($rows[$uid]->lookup('FLAGS')?->values()??[]):[];$out[$uid]=['seen'=>in_array('\\Seen',$flags,true),'missing'=>!isset($rows[$uid])||in_array('\\Deleted',$flags,true)];}return $out;}
 public function seen(string $folder,int $uid,bool $seen):void {$this->select($folder);$this->uids([$uid],1);$this->command(fn()=>$this->connection->store(['\\Seen'],$uid,mode:$seen?'+':'-'));}
 public function move(string $folder,int $uid,string $target):void {$this->select($folder);$this->uids([$uid],1);if($target===$folder||!in_array($target,$this->folders(),true))throw new RuntimeException('Zielordner nicht bestätigt.');$cap=$this->command(fn()=>$this->connection->capability());$caps=array_map(fn($v)=>strtoupper((string)$v->value),$cap->tokensAfter(2));if(!in_array('MOVE',$caps,true))throw new RuntimeException('Server unterstützt kein sicheres UID-MOVE; Nachricht im bestehenden Mailprogramm verschieben.');$this->command(fn()=>$this->connection->move($target,$uid));}
 public function append(string $folder,string $raw):void {if(strlen($raw)>15*1024*1024)throw new RuntimeException('IMAP-Kopie überschreitet15MB.');$this->select($folder);$this->command(fn()=>$this->connection->append($folder,$raw,['\\Seen']));}
 public function findMessageId(string $folder,string $messageId):array {
  if(!preg_match('/^<[a-f0-9]{32}@gsz\.internal>$/D',$messageId))throw new RuntimeException('Nachrichtenidentität ungültig.');$valid=$this->validity($folder);$this->select($folder);$r=$this->command(fn()=>$this->connection->search(['HEADER Message-ID "'.$messageId.'"']));$ids=$this->uids(array_map(fn($x)=>$x->value,$r->tokensAfter(2)),100);$rows=$this->fetched($ids,['BODY.PEEK[HEADER]','FLAGS']);$found=[];$deleted=[];foreach($ids as $uid){$data=$rows[$uid]??null;$head=$data?->lookup('[HEADER]')?->value;if(!is_string($head)||strlen($head)>262144)throw new RuntimeException('Identität unvollständig.');$h=gszMimeHeaders($head);$identity=$h['message-id']??'';if($identity!==$messageId){if(str_contains($identity,$messageId))throw new RuntimeException('Nachrichtenidentität mehrdeutig.');continue;}$flags=$data->lookup('FLAGS')?->values()??[];if(in_array('\\Deleted',$flags,true))$deleted[]=$uid;else$found[]=$uid;}if($this->validity($folder)!==$valid)throw new RuntimeException('UIDVALIDITY während Suche geändert.');return ['uidvalidity'=>$valid,'uids'=>$found,'deleted_uids'=>$deleted];
 }
}
function gszMailSafeError(Throwable $e):string {$s=$e->getMessage();return preg_match('/auth|login|password|credential/i',$s)?'IMAP-Anmeldung nicht bestätigt. Postfachzugang prüfen.':(preg_match('/certificate|ssl|tls/i',$s)?'IMAP-TLS/Zertifikat nicht bestätigt.':(preg_match('/timed? ?out|timeout|zeitlimit/i',$s)?'IMAP-Zeitüberschreitung.':'IMAP-Vorgang nicht bestätigt; Verbindung, Identität und Größenlimit prüfen.'));}
